
(()=>{'use strict';if(window.__amaMobileGesturesReady)return;window.__amaMobileGesturesReady=true;const touchDevice=window.matchMedia('(any-pointer: coarse)');const preventGestureZoom=event=>{if(touchDevice.matches&&event.cancelable)event.preventDefault();};document.addEventListener('gesturestart',preventGestureZoom,{passive:false});document.addEventListener('gesturechange',preventGestureZoom,{passive:false});document.addEventListener('touchmove',event=>{if(event.touches&&event.touches.length>1)preventGestureZoom(event);},{passive:false});})();
